{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Tropisetron, a tertiary N-methyl tropane ester, has an absolute oral bioavailability of 52% at a 20 mg oral dose in healthy volunteers, demonstrating that this scaffold can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Cocaine, another tertiary N-methyl tropane ester, has an oral bioavailability of 20-30% in humans, supporting that the query's structural class can reach or exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ipratropium, a quaternary ammonium tropane ester, has only about 2% oral bioavailability in healthy volunteers, but this very low value is driven by the permanent positive charge, which is absent in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiotropium, a quaternary ammonium tropane epoxide, has 2-3% absolute oral bioavailability from an oral solution, but again the quaternary ammonium group, not present in the query, is the major absorption barrier.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the query is a tertiary N-methyl tropane ester; tertiary tropane esters such as tropisetron and cocaine show moderate-to-high oral bioavailability, whereas the very low values for quaternary analogues like ipratropium and tiotropium are not transferable due to the absence of the quaternary ammonium charge.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself.",
    "The threshold is borderline if the true oral bioavailability is near 20%.",
    "Limited evidence specifically addressing the effect of the epoxide bridge and tropic acid ester on first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

